if(mode==='handoff' || mode==='order' || mode==='ozet') konuDisi=false;
// KONUM KESIN GARANTI: konum sorulunca her zaman veri tabanindaki adres+link verilir
const locIntent=/(konum|neredesiniz|nerdesiniz|adresiniz|nasil gel|yol tarif|harita)/.test(ptxt) && !/(siparis|nerede kaldi|ne zaman|kac dakika|kac dk)/.test(ptxt);
