else if(mode==='konudisi'){ mode='reply'; konuDisi=false; customerText='Tabii, size yardımcı olmak isterim. Tam olarak ne istediğinizi yazar mısınız?'; }

// DETERMINISTIK ONAY: musteri onayladi ve gecmiste ozet gosterildiyse, modelin o anki JSON'una bagli kalmadan siparisi gecir
{
  const onayNet=/(\bevet\b|\btamam\w*|\bolur\b|\bolsun\b|onayl\w*|gecebilir|gecsin|kesinlikle|tabii ki|\bdogru\b|onaylarim)/.test(ptxt);
  let oncedenOzet=false;
