function pTSx(s){ s=(s||'').toString().trim(); const a=s.split(' '); const d=(a[0]||'').split('.'); const t=(a[1]||'0:0').split(':'); if(d.length<3) return 0; return Date.UTC(+d[2],(+d[1])-1,+d[0],+t[0],+(t[1]||0)); }
const sonlar=$('16b Son Siparis').all().map(i=>i.json).filter(r=>r&&r.siparis_no);
const yeniUrun=satir.join(' ; ');
