if(sonlar.length){ const son=sonlar[sonlar.length-1]; const dkx=(pTSx(p.tarihSaat)-pTSx(son.olusturma))/60000; if(dkx>=0 && dkx<5 && String(son.urunler||'').trim()===yeniUrun.trim()) tekrar=true; }
