function norm(s){return (s||'').toString().trim().toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i');}
function normTel(s){ let x=String(s||'').replace(/[^0-9]/g,''); if(!x) return ''; if(x.length===11 && x[0]==='0') x='90'+x.slice(1); else if(x.length===10 && x[0]==='5') x='90'+x; return x; }
