function secimNo(input, n, labels){
  const s=String(input||'').trim();
  const m=s.match(/^(\d+)\b/);
  if(m){ const num=parseInt(m[1],10); if(num>=1 && num<=n) return num; }
  const x=norm(s);
  for(let i=1;i<=n;i++){ const lab=norm(labels[i]||''); if(!lab) continue; if(x===lab) return i; if(x.length>=3 && (lab.indexOf(x)===0 || x.indexOf(lab)===0)) return i; }
