}


const oturum = ($('Admin Oturum Oku').all().map(i=>i.json).filter(r=>r&&String(r.telefon).trim()===telefon.trim())[0]) || {};
let adim = (oturum.adim||'').toString().trim();
let kategori = (oturum.kategori||'').toString().trim();
