let oturum_ekle_tel = (oturum.ekle_tel||'').toString().trim();
let oturum_ekle_kod = (oturum.ekle_kod||'').toString().trim();

const musteriler = $('Admin Musteriler').all().map(i=>i.json).filter(r=>r&&r.telefon);
const siparisler = $('Admin Siparisler').all().map(i=>i.json).filter(r=>r&&r.telefon);
const banliRows = $('Admin Banlilar').all().map(i=>i.json).filter(r=>r&&r.telefon);
