const bekleyenEgitim = egitim.filter(e=>String(e.durum||'').trim().toLowerCase()==='beklemede');
const banli = new Set(banliRows.map(r=>String(r.telefon).trim()));

function pTS(s){ s=(s||'').toString().trim(); const a=s.split(' '); const dd=(a[0]||'').split('.'); const tt=(a[1]||'0:0').split(':'); if(dd.length<3) return 0; return Date.UTC(+dd[2],(+dd[1])-1,+dd[0],+tt[0],+(tt[1]||0)); }
const now=Date.now(), gunMs=86400000;
const bugun = new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date()).replace(/\//g,'.');

const stats={};
for(const o of siparisler){ const t=String(o.telefon).trim(); if(!stats[t]) stats[t]={count:0,last:0,spend:0}; stats[t].count++; const ms=pTS(o.olusturma); if(ms>stats[t].last) stats[t].last=ms; stats[t].spend+=Number(o.toplam)||0; }

const SENARYO = {
 1:'Merhaba {ad}, sizi bir süredir göremedik ve özledik. Küçük bir teşekkür olarak, bu hafta vereceğiniz siparişte içecek ikramımız bizden olsun. Sipariş vermek isterseniz bu mesaja yazmanız yeterli, size yardımcı olalım.',
 2:'Merhaba {ad}, hafta içi saat 14 ile 18 arasında siparişlerinizde yüzde 10 indirim sizi bekliyor. Öğleden sonra bir şeyler atıştırmak isterseniz bu mesaja yazmanız yeterli.',
 3:'Merhaba {ad}, ilk siparişiniz için teşekkür ederiz, umarız beğenmişsinizdir. İkinci siparişinizde sizi küçük bir ikram bekliyor. Sipariş vermek isterseniz bu mesaja yazabilirsiniz.',
 4:'Merhaba {ad}, bizi sık sık tercih ettiğiniz için teşekkür ederiz. Bir sonraki siparişinizde size küçük bir teşekkür ikramımız olacak. Dilediğinizde bu mesaja yazarak sipariş verebilirsiniz.',
 5:'Merhaba {ad}, akşam yemeği için sıcacık dönerimiz ve menülerimiz hazır. Canınız isterse bu mesaja yazmanız yeterli, kapınıza kadar getirelim.',
 6:'Merhaba {ad}, sadakat kartınızda ödüle az kaldı. Birkaç sipariş daha verdiğinizde bir siparişiniz bizden ücretsiz olacak. Sipariş vermek isterseniz bu mesaja yazabilirsiniz.'
};
const SENARYO_AD = {1:'Geri kazanım (özledik ve ikram)',2:'Happy hour indirimi',3:'İkinci sipariş (yeni müşteri)',4:'Sadık müşteriye özel',5:'Genel sıcak davet',6:'Sadakat hatırlatma'};
const KATEGORI_AD = {1:'Herkes',2:'Son 30 günde sipariş vermeyenler',3:'Son 7 günde sipariş verenler',4:'Düzenli (3 ve üzeri sipariş)',5:'Sadece 1 sipariş verenler',6:'Hiç sipariş vermemiş',7:'Yüksek harcayanlar (1000 TL ve üzeri)'};

const MESAJ_SECENEK='Hangi mesajı göndereyim? Numarasını yazın:\n1) '+SENARYO_AD[1]+'\n2) '+SENARYO_AD[2]+'\n3) '+SENARYO_AD[3]+'\n4) '+SENARYO_AD[4]+'\n5) '+SENARYO_AD[5]+'\n6) '+SENARYO_AD[6]+'\n7) Kendi mesajımı yazacağım';
const KATEGORI_SORU='Kimlere gönderelim? Numarasını yazın:\n1) '+KATEGORI_AD[1]+'\n2) '+KATEGORI_AD[2]+'\n3) '+KATEGORI_AD[3]+'\n4) '+KATEGORI_AD[4]+'\n5) '+KATEGORI_AD[5]+'\n6) '+KATEGORI_AD[6]+'\n7) '+KATEGORI_AD[7];

const YARDIM='Restoran Bot yönetici konsolu. Şu komutları yazabilirsiniz:\n\nÖzet : işletmenin özeti.\nBugün : bugünkü siparişler.\nSiparişler : son siparişler.\nBanlılar : banlı numaralar.\nMüşteri 905... : o numaranın bilgisi ve sadakat durumu.\nNumara ekle: 905... : bir müşteriyi kampanya listesine ekler.\nKampanya : toplu mesaj gönderme sihirbazını başlatır.\nEğitim : sistemin öğrendiği bekleyen önerileri gösterir.\nOnayla 1 : o öneriyi uygular (bölge ya da menü güncellenir).\nReddet 1 : o öneriyi siler.\nDevral 905... : o sohbette botu durdurur, siz yürütürsünüz.\nBirak 905... : o sohbeti tekrar bota verir.\nİptal : devam eden işlemi durdurur.\nYardım : bu menüyü gösterir.\n\nNumara ekleme nasıl olur:\n1. Numara ekle: 05321362256 yazın (numarayı 0 ile, 0 olmadan ya da +90 ile yazabilirsiniz, sistem otomatik düzeltir).\n2. O numaraya 4 haneli bir onay kodu gider.\n3. Müşteriden aldığınız kodu bana yazın, doğruysa listeye eklenir.\n(Müşteri daha önce sipariş verdiyse yeniden eklenmez, size sadakat durumu söylenir.)\n\nKampanya nasıl gönderilir:\n1. Kampanya yazın.\n2. Mesajı seçin (1 ile 6 hazır, 7 kendi mesajınız).\n3. Kimlere gideceğini seçin (1 ile 7 kategori).\n4. Özeti görün, Evet ile gönderin, Hayır ile iptal.\n\nMesaja {ad} yazarsanız her müşteriye adıyla gider. Ret diyen ve banlı numaralara gönderilmez.';

function kisiSec(m){
  const t=String(m.telefon).trim();
  if(banli.has(t)) return false;
  const riza=String(m.pazarlama_rizasi||'').trim().toLowerCase();
  if(riza==='ret'||riza==='hayir'||riza==='red'||riza==='false'||riza==='0') return false;
  const s=stats[t]||{count:0,last:0,spend:0};
  const k=parseInt(kategori,10);
  if(k===1) return true;
  if(k===2) return !(s.last && (now-s.last)<30*gunMs);
  if(k===3) return !!(s.last && (now-s.last)<7*gunMs);
  if(k===4) return s.count>=3;
  if(k===5) return s.count===1;
  if(k===6) return s.count===0;
  if(k===7) return s.spend>=1000;
  return false;
}
function kisilestir(t,ad){ let x=String(t).split('{ad}').join(ad||''); x=x.replace(/ +([,.!?])/g,'$1').replace(/ {2,}/g,' ').trim(); return x; }
function hesapla(){ const out=[]; for(const m of musteriler){ if(!kisiSec(m)) continue; const t=String(m.telefon).trim(); const ad=String(m.son_ad||'').trim(); out.push({ telefon:t, ad:ad, segment:(KATEGORI_AD[parseInt(kategori,10)]||kategori), mesaj:kisilestir(mesaj,ad), bekle_sn:(Math.floor(Math.random()*9)+6) }); } return out; }

function loyaltyDurumAdmin(T){
  if(T<=0) return 'Henüz sipariş vermemiş, sadakat kartı boş.';
  const s=T%10;
  if(s===0) return T+' sipariş vermiş. Son siparişi ödülüydü, kartı yeni başladı, ödüle 9 sipariş kaldı.';
  if(s===9) return T+' sipariş vermiş. Kartı doldu, bir sonraki siparişi ücretsiz olacak.';
  return T+' sipariş vermiş. Kartında '+s+' damga var, ödüle '+(9-s)+' sipariş kaldı.';
}
function loyaltyMesajMusteri(T){
  if(T<=0) return 'Merhaba, sadakat kartınız hazır. Her 9 siparişten sonra bir siparişiniz bizden ücretsiz. Sizi bekliyoruz.';
  const s=T%10;
  if(s===9) return 'Merhaba, sadakat kartınız doldu, bir sonraki siparişiniz bizden ücretsiz olacak. Sizi tekrar görmek isteriz.';
  if(s===0) return 'Merhaba, sizi tekrar görmek isteriz. Yeni sadakat kartınız başladı, ödüle 9 sipariş kaldı.';
  return 'Merhaba, sadakat kartınızda '+s+' damga var, ödüle '+(9-s)+' sipariş kaldı. Sizi tekrar görmek isteriz.';
}

function bareNum(t){ return String(t||'').split('@')[0]; }
function ozetMetni(){ let bs=0,bc=0; for(const o of siparisler){ if(String(o.olusturma||'').indexOf(bugun)===0){ bs++; bc+=Number(o.toplam)||0; } } return 'Özet ('+bugun+')\nToplam müşteri: '+musteriler.length+'\nBugün sipariş: '+bs+'\nBugün ciro: '+bc+' TL\nBanlı numara: '+banli.size; }
function bugunMetni(){ const li=siparisler.filter(o=>String(o.olusturma||'').indexOf(bugun)===0); if(!li.length) return 'Bugün ('+bugun+') henüz sipariş yok.'; let toplam=0; const sat=li.slice(-15).map(o=>{ toplam+=Number(o.toplam)||0; return (o.siparis_no||'')+' . '+bareNum(o.telefon)+' . '+(o.toplam||0)+' TL . '+(o.durum||''); }); return 'Bugünkü siparişler ('+li.length+' adet):\n'+sat.join('\n')+'\nToplam ciro: '+toplam+' TL'; }
function siparislerMetni(){ const li=siparisler.slice().sort((a,b)=>pTS(b.olusturma)-pTS(a.olusturma)).slice(0,10); if(!li.length) return 'Henüz sipariş yok.'; const sat=li.map(o=>(o.siparis_no||'')+' . '+bareNum(o.telefon)+' . '+(o.toplam||0)+' TL . '+(o.durum||'')+' . '+(o.olusturma||'')); return 'Son '+li.length+' sipariş:\n'+sat.join('\n'); }
function banliMetni(){ if(!banliRows.length) return 'Banlı numara yok.'; const sat=banliRows.slice(0,30).map(b=>bareNum(b.telefon)+' . '+(b.sebep||'')+' . '+(b.tarih||'')); return 'Banlı numaralar ('+banliRows.length+'):\n'+sat.join('\n'); }
function musteriMetni(num){ if(!num) return 'Numara yazmalısınız. Örnek: Müşteri 905301112233'; const m=musteriler.filter(x=>bareNum(x.telefon).indexOf(num)>=0)[0]; if(!m) return 'Bu numaralı müşteri bulunamadı: '+num; const t=String(m.telefon).trim(); const s=stats[t]||{count:0,last:0,spend:0}; const son = s.last? new Date(s.last).toISOString().slice(0,10).split('-').reverse().join('.') : 'yok'; const riza=String(m.pazarlama_rizasi||'').trim()||'belirtilmemiş'; return 'Müşteri '+bareNum(t)+'\nAd: '+(m.son_ad||'')+'\nSipariş sayısı: '+s.count+'\nToplam harcama: '+s.spend+' TL\nSon sipariş: '+son+'\nPazarlama izni: '+riza+'\n'+loyaltyDurumAdmin(s.count); }

