        }
        else if(cmd==='egitim'||cmd==='oneriler'||cmd==='öneriler'){
    if(!bekleyenEgitim.length){ yanit='Bekleyen eğitim önerisi yok. Sistem konuşmalardan öğrendikçe buraya öneri düşer.'; }
