const _i=$('1 Mesaji Coz').item.json; if(_i.kaynakApi===true){ return [{ json:{ eko:true } }]; }
const inc=$('1 Mesaji Coz').item.json;
const txt=(inc.text||'').trim();
const tel=String(inc.telefon||'');
function pTSx(s){ s=(s||'').toString().trim(); const a=s.split(' '); const d=(a[0]||'').split('.'); const t=(a[1]||'0:0').split(':'); if(d.length<3) return 0; return Date.UTC(+d[2],(+d[1])-1,+d[0],+t[0],+(t[1]||0)); }
const now=pTSx(inc.tarihSaat);
const rows=$('Eko Mesaj Oku').all().map(i=>i.json).filter(r=>r&&r.telefon);
let eko=false;
if(txt){ for(const r of rows){ if(String(r.telefon)!==tel) continue; if(String(r.yon||'')!=='giden') continue; if(String(r.metin||'').trim()!==txt) continue; const dk=(now-pTSx(r.zaman))/60000; if(dk>=-2 && dk<6){ eko=true; break; } } }
return [{ json:{ eko } }];

const p=$('20 Ciktiyi Ayristir').item.json;
const g=$('5 Gorusmeyi Bul').item.json||{};
function num(x){ const n=Number(x); return isNaN(n)?0:n; }
const durum=(g.durum||'').toString().trim().toLowerCase();
const kadar=num(g.ai_duraklat_kadar);
let mevcut=num(g.uyari_sayisi);
if(durum==='dondur' && !(kadar>0 && Date.now()<kadar)) mevcut=0;
const konuDisi=!!p.konuDisi;
let yeni, sifirla=false;
if(konuDisi){ yeni=mevcut+1; }
else { yeni=0; sifirla=(mevcut>0); }
const dondu=(konuDisi && yeni>=5);
let cikisMetin='';
if(dondu){ cikisMetin='Sipariş dışı çok fazla mesaj geldiği için bu sohbete kısa bir ara veriyorum. Birazdan tekrar yazabilirsiniz.'; }
else if(p.mode==='konudisi'){ cikisMetin=p.customerText||'Ben sadece Restoran Bot sipariş ve menü konusunda yardımcı olabiliyorum, size sipariş ya da menü konusunda nasıl yardımcı olayım?'; }
else if(konuDisi){ cikisMetin='Size yardımcı olmak isterim ama lütfen nazik bir dil kullanalım. Sipariş ya da menü konusunda nasıl yardımcı olabilirim?'; }
return [{ json: Object.assign({}, p, { konuDisi, yeni, dondu, sifirla, cikisMetin, dondurKadar:(Date.now()+900000) }) }];

const p=$('1 Mesaji Coz').item.json;
