let out=''; try{ out=$json.choices[0].message.content||''; }catch(e){ out=''; }
const norm=out.toString().toUpperCase();
const p=$('1 Mesaji Coz').item.json;
const t=(p.text||'').toString().toLowerCase().replace(/\u0131/g,'i').replace(/\u015f/g,'s').replace(/\u011f/g,'g').replace(/\u00fc/g,'u').replace(/\u00f6/g,'o').replace(/\u00e7/g,'c').trim();
const kelimeSay=t.split(/\s+/).filter(Boolean).length;
const onayKelime = kelimeSay<=3 && /(\bevet\b|\bhayir\b|\btamam\w*|\bolur\b|\bolsun\b|onayl\w*|\bpeki\b|\boldu\b|\bok\b|\bokey\b|\bokay\b|aynis\w*|\baynen\b|\bdevam\b|\bbasla\w*|vazgec\w*|\biptal\b|\bdur\b|\bbekle\b|\byok\b|\bvar\b|\bkesinlikle\b|\bgecsin\b|\bgec\b|tesekkur\w*|sagol\w*|\beyvallah\b)/.test(t);
const disarida = (norm.indexOf('DISARIDA')>=0 && norm.indexOf('ICERIDE')<0) && !onayKelime;
const iceride = !disarida;
const g=$('5 Gorusmeyi Bul').item.json||{};
function num(x){ const n=Number(x); return isNaN(n)?0:n; }
let mevcut=num(g.uyari_sayisi);
const kadar0=num(g.ai_duraklat_kadar);
const durum0=(g.durum||'').toString().trim().toLowerCase();
if(durum0==='dondur' && !(kadar0>0 && Date.now()<kadar0)) mevcut=0;
const yeni = disarida ? (mevcut+1) : 0;
const dondu = disarida && yeni>=5;
const kadar = Date.now()+900000;
const mesaj = dondu ? 'Sipariş dışı çok fazla mesaj geldiği için bu sohbete kısa bir ara veriyorum. Birazdan tekrar yazabilirsiniz.' : 'Ben sadece Restoran Bot sipariş ve menü konusunda yardımcı olabiliyorum, size sipariş ya da menü konusunda nasıl yardımcı olayım?';
return [{ json:{ iceride, disarida, yeni, dondu, kadar, mesaj, telefon:p.telefon, number:p.number } }];
